CREATE TABLE courses(id TEXT PRIMARY KEY,name TEXT NOT NULL,slug TEXT NOT NULL UNIQUE,sort_order INTEGER NOT NULL DEFAULT 0,is_test INTEGER NOT NULL DEFAULT 0);
CREATE TABLE semesters(id TEXT PRIMARY KEY,course_id TEXT NOT NULL REFERENCES courses(id),name TEXT NOT NULL,slug TEXT NOT NULL,sort_order INTEGER NOT NULL DEFAULT 0,is_test INTEGER NOT NULL DEFAULT 0,UNIQUE(course_id,slug));
CREATE TABLE chapters(id TEXT PRIMARY KEY,semester_id TEXT NOT NULL REFERENCES semesters(id),name TEXT NOT NULL,slug TEXT NOT NULL,sort_order INTEGER NOT NULL DEFAULT 0,is_test INTEGER NOT NULL DEFAULT 0,UNIQUE(semester_id,slug));
CREATE TABLE topics(id TEXT PRIMARY KEY,chapter_id TEXT NOT NULL REFERENCES chapters(id),name TEXT NOT NULL,slug TEXT NOT NULL,sort_order INTEGER NOT NULL DEFAULT 0,is_test INTEGER NOT NULL DEFAULT 0,UNIQUE(chapter_id,slug));
CREATE TABLE subtopics(id TEXT PRIMARY KEY,topic_id TEXT NOT NULL REFERENCES topics(id),name TEXT NOT NULL,slug TEXT NOT NULL,sort_order INTEGER NOT NULL DEFAULT 0,is_test INTEGER NOT NULL DEFAULT 0,UNIQUE(topic_id,slug),UNIQUE(id,topic_id));
CREATE TABLE difficulty_levels(id TEXT PRIMARY KEY,name TEXT NOT NULL,slug TEXT NOT NULL UNIQUE,sort_order INTEGER NOT NULL DEFAULT 0);
CREATE TABLE questions(id TEXT PRIMARY KEY,question_code TEXT NOT NULL UNIQUE,topic_id TEXT NOT NULL REFERENCES topics(id),subtopic_id TEXT,title TEXT NOT NULL,scenario TEXT NOT NULL,difficulty_id TEXT NOT NULL REFERENCES difficulty_levels(id),question_type TEXT NOT NULL CHECK(question_type IN ('structured','multiple_choice','short_answer','essay')),total_marks INTEGER NOT NULL CHECK(total_marks>0),estimated_minutes INTEGER NOT NULL CHECK(estimated_minutes>0),status TEXT NOT NULL CHECK(status IN ('draft','reviewing','approved','retired')),contains_diagram INTEGER NOT NULL,contains_graph INTEGER NOT NULL,contains_fbd INTEGER NOT NULL,active_version INTEGER NOT NULL DEFAULT 1,created_at TEXT NOT NULL,updated_at TEXT NOT NULL,approved_at TEXT,FOREIGN KEY(subtopic_id,topic_id) REFERENCES subtopics(id,topic_id));
CREATE TABLE question_parts(question_id TEXT NOT NULL REFERENCES questions(id),id TEXT NOT NULL,label TEXT NOT NULL,prompt TEXT NOT NULL,marks INTEGER NOT NULL CHECK(marks>=0),display_order INTEGER NOT NULL,parent_id TEXT,PRIMARY KEY(question_id,id),FOREIGN KEY(question_id,parent_id) REFERENCES question_parts(question_id,id) DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE solutions(question_id TEXT NOT NULL,part_id TEXT NOT NULL,solution TEXT NOT NULL,equation_latex TEXT NOT NULL,teacher_notes TEXT NOT NULL,PRIMARY KEY(question_id,part_id),FOREIGN KEY(question_id,part_id) REFERENCES question_parts(question_id,id));
CREATE TABLE solution_steps(question_id TEXT NOT NULL,part_id TEXT NOT NULL,step_number INTEGER NOT NULL,explanation TEXT NOT NULL,equation_latex TEXT NOT NULL,working TEXT NOT NULL,marking_point TEXT NOT NULL,marks INTEGER NOT NULL CHECK(marks>=0),display_order INTEGER NOT NULL,PRIMARY KEY(question_id,part_id,step_number),FOREIGN KEY(question_id,part_id) REFERENCES solutions(question_id,part_id));
CREATE TABLE hints(question_id TEXT NOT NULL REFERENCES questions(id),id TEXT NOT NULL,part_id TEXT,hint_text TEXT NOT NULL,display_order INTEGER NOT NULL,PRIMARY KEY(question_id,id),FOREIGN KEY(question_id,part_id) REFERENCES question_parts(question_id,id));
CREATE TABLE assets(question_id TEXT NOT NULL REFERENCES questions(id),id TEXT NOT NULL,part_id TEXT,kind TEXT NOT NULL,url TEXT NOT NULL,alt TEXT NOT NULL,mime TEXT NOT NULL,display_order INTEGER NOT NULL,PRIMARY KEY(question_id,id),FOREIGN KEY(question_id,part_id) REFERENCES question_parts(question_id,id));
CREATE TABLE tags(id TEXT PRIMARY KEY,name TEXT NOT NULL,normalized TEXT NOT NULL UNIQUE);
CREATE TABLE question_tags(question_id TEXT NOT NULL REFERENCES questions(id),tag_id TEXT NOT NULL REFERENCES tags(id),PRIMARY KEY(question_id,tag_id));
CREATE TABLE question_versions(question_id TEXT NOT NULL REFERENCES questions(id),version_number INTEGER NOT NULL,snapshot TEXT NOT NULL CHECK(json_valid(snapshot)),change_note TEXT NOT NULL,author TEXT,created_at TEXT NOT NULL,PRIMARY KEY(question_id,version_number));
CREATE TABLE revision_candidates(id TEXT PRIMARY KEY,question_id TEXT NOT NULL REFERENCES questions(id),base_version INTEGER NOT NULL,source TEXT NOT NULL CHECK(source IN ('manual','json','pdf')),source_pdf_url TEXT,snapshot TEXT NOT NULL CHECK(json_valid(snapshot)),change_note TEXT NOT NULL,author TEXT,status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','approved','rejected')),created_at TEXT NOT NULL,reviewed_at TEXT,reviewer TEXT);
CREATE INDEX semesters_course ON semesters(course_id);
CREATE INDEX chapters_semester ON chapters(semester_id);
CREATE INDEX topics_chapter ON topics(chapter_id);
CREATE INDEX subtopics_topic ON subtopics(topic_id);
CREATE INDEX questions_browse ON questions(topic_id,difficulty_id,status,total_marks);
CREATE INDEX questions_status_difficulty ON questions(status,difficulty_id,total_marks);
CREATE INDEX questions_subtopic ON questions(subtopic_id);
CREATE INDEX questions_marks ON questions(total_marks);
CREATE INDEX question_tags_tag ON question_tags(tag_id,question_id);
CREATE INDEX revisions_question ON revision_candidates(question_id,status);
CREATE VIRTUAL TABLE question_search USING fts5(question_id UNINDEXED,search_text,tokenize='unicode61');
CREATE TRIGGER versions_immutable_update BEFORE UPDATE ON question_versions BEGIN SELECT RAISE(ABORT,'Historical versions are immutable'); END;
CREATE TRIGGER versions_immutable_delete BEFORE DELETE ON question_versions BEGIN SELECT RAISE(ABORT,'Historical versions are immutable'); END;
